// Defines an Abstract Base Class (ABC)
class Shape {
public:
    // Pure Virtual Function: Class is now Abstract
    // Compiler sets vtable entry to zero/error handler
    virtual double area() const = 0;

    // Pure virtual functions can still have definitions,
    // but must be called explicitly using Scope Resolution Op.
    // virtual void draw() = 0;

    virtual ~Shape() = default;
};

// Cannot instantiate: Shape s;

class Circle : public Shape {
    double radius;
public:
    Circle(double r) : radius(r) {}
    // Must implement all pure virtual methods
    double area() const override {
        return 3.14159 * radius * radius;
    }
};

// Can instantiate: Circle c(10.0);
Shape* ptr = new Circle(5.0);
